import { NextFunction, Request, Response, Router } from 'express';
import { TaskService } from '../application/task-service';
import { ConflictError, DomainError, NotFoundError } from '../domain/errors';

type CreateUserBody = { name?: unknown };
type CreateProjectBody = { name?: unknown };
type CreateTaskBody = {
  title?: unknown;
  description?: unknown;
  dueDate?: unknown;
  status?: unknown;
  assigneeId?: unknown;
};

const requiredString = (value: unknown, field: string): string => {
  if (typeof value !== 'string') throw new DomainError(`${field} must be a string`);
  return value;
};

const optionalString = (value: unknown, field: string): string | undefined => {
  if (value === undefined) return undefined;
  return requiredString(value, field);
};

const queryString = (value: unknown, field: string): string | undefined => {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') throw new DomainError(`${field} must be a string`);
  return value;
};

export class TaskController {
  public constructor(private readonly service: TaskService) {}

  public router(): Router {
    const router = Router();
    router.post('/users', this.createUser);
    router.post('/projects', this.createProject);
    router.post('/projects/:projectId/tasks', this.createTask);
    router.get('/projects/:projectId/tasks', this.listTasks);
    router.patch('/tasks/:taskId/done', this.markTaskDone);
    return router;
  }

  public errorHandler(error: unknown, _request: Request, response: Response, _next: NextFunction): void {
    if (error instanceof NotFoundError) {
      response.status(404).json({ error: error.message });
      return;
    }
    if (error instanceof ConflictError) {
      response.status(409).json({ error: error.message });
      return;
    }
    if (error instanceof DomainError) {
      response.status(400).json({ error: error.message });
      return;
    }
    response.status(500).json({ error: 'Internal server error' });
  }

  private createUser = (request: Request<unknown, unknown, CreateUserBody>, response: Response): void => {
    const user = this.service.createUser({ name: requiredString(request.body.name, 'name') });
    response.status(201).json(user);
  };

  private createProject = (request: Request<unknown, unknown, CreateProjectBody>, response: Response): void => {
    const project = this.service.createProject({ name: requiredString(request.body.name, 'name') });
    response.status(201).json(project);
  };

  private createTask = (request: Request<{ projectId: string }, unknown, CreateTaskBody>, response: Response): void => {
    const task = this.service.createTask(request.params.projectId, {
      title: requiredString(request.body.title, 'title'),
      description: requiredString(request.body.description, 'description'),
      dueDate: optionalString(request.body.dueDate, 'dueDate'),
      status: optionalString(request.body.status, 'status'),
      assigneeId: optionalString(request.body.assigneeId, 'assigneeId'),
    });
    response.status(201).json(task);
  };

  private listTasks = (request: Request<{ projectId: string }>, response: Response): void => {
    const tasks = this.service.listTasks(request.params.projectId, {
      status: queryString(request.query.status, 'status'),
      assigneeId: queryString(request.query.assigneeId, 'assigneeId'),
    });
    response.json(tasks);
  };

  private markTaskDone = (request: Request<{ taskId: string }>, response: Response): void => {
    response.json(this.service.markTaskDone(request.params.taskId));
  };
}

